type Suit struct{ key string }

var Clubs, Diamonds = Suit{"clubs"}, Suit{"diamonds"}

func FromString(raw string) (Suit, error) {
	switch raw {
	case Clubs.key:
		return Clubs, nil
	case Diamonds.key:
		return Diamonds, nil
	}
	return Suit{}, fmt.Errorf("unknown suit: %q", raw)
}

